"""Real fork/pipe/wait/signals with synthetic worker, host and stock ARM libc."""
from pathlib import Path
import hashlib,json,subprocess
ROOT=Path(__file__).resolve().parents[1];work=ROOT/'work/qqmusic-worker';work.mkdir(exist_ok=True)
(work/'report.json').unlink(missing_ok=True)
core=['runtime/apps/qqmusic/qqmusic_worker.c','runtime/apps/qqmusic/qqmusic_protocol.c','runtime/apps/qqmusic/qqmusic_session.c','runtime/apps/qqmusic/qqmusic_resource.c','runtime/apps/qqmusic/qqmusic_json.c','runtime/apps/qqmusic/qqmusic_cgi.c','runtime/apps/qqmusic/qqmusic_credential.c','runtime/store/https_url.c','runtime/native/linux_process_posix.c','runtime/native/linux_signals_posix.c','tools/fixtures/qqmusic_worker.c']
flags=['-std=c99','-D_DEFAULT_SOURCE','-Wall','-Wextra','-Werror']
host=work/'worker-tests.sanitized';subprocess.run(['gcc-12',*flags,'-O1','-g','-fsanitize=address,undefined',*core,'-o',str(host)],cwd=ROOT,check=True);subprocess.run([str(host)],cwd=ROOT,check=True,timeout=60)
lib=ROOT/'work/arm-signal-tests/lib'
for name,digest in {'libc.so.6':'5afbf3074dfa9ba0478d6670f220ef4d7ec065a255ee856d9093d39210f23812','ld-linux.so.3':'2f007b0809684fde0ac446ad203135c10b4318eb8c10d4160a9f59b32c3c52de'}.items():assert hashlib.sha256((lib/name).read_bytes()).hexdigest()==digest
arm=work/'worker-tests.arm'
subprocess.run(['arm-linux-gnueabi-gcc',*flags,'-Os','-march=armv5te','-marm','-mfloat-abi=soft','-ffreestanding','-fno-builtin','-fno-pie','-nostdlib','-no-pie','-Wl,--hash-style=sysv','-Wl,--build-id=none','-Wl,--dynamic-linker=/lib/ld-linux.so.3',*core,'runtime/store/stock_tls_compat.c','runtime/store/start.c','runtime/store/start.S',str(lib/'libc.so.6'),str(lib/'ld-linux.so.3'),'-lgcc','-o',str(arm)],cwd=ROOT,check=True)
subprocess.run(['qemu-arm','-cpu','arm926',str(lib/'ld-linux.so.3'),'--library-path',str(lib),str(arm)],cwd=ROOT,check=True,timeout=60)
report={'passed':True,'scope':'actual_native_worker_process_and_ipc_with_synthetic_job','physical_device_tested':False,'real_account_tested':False,'cases':['copied request survives parent wiping','parent request cleared after fork','child detach leaves parent descriptors intact','published progress withheld until successful reap','worker failure and detach failure','abrupt exit becomes review','failure after publication becomes review','cooperative cancellation','ignored TERM escalates to KILL and reaps only owned child','unrelated sibling remains alive','full progress pipe cannot block parent or create sequence gaps','bad progress cannot produce success','malformed IPC refuses success','truncated IPC refuses success','exit zero without final IPC becomes review','repeat cancel and fd count baseline','network pending creates no pipe or child','cancel/denial/expiry/stop during network preparation clears request without fork','ready network forks once and uses copied authorization','network callbacks run only before fork in parent'],'sources':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in core+['runtime/apps/qqmusic/qqmusic_worker.h','runtime/apps/qqmusic/qqmusic_runtime.h']},'arm_sha256':hashlib.sha256(arm.read_bytes()).hexdigest(),'limits':['Worker callback is synthetic, not actual download/conversion/publication.','No production child detach or recovery/journal adapter bound.','Fork and pipe run on PC host and ARM user emulation, not physical Sony process qualification.']}
(work/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='sources'},indent=2))
